{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Celiprolol, the closest analogue sharing the tert-butylamino-hydroxypropoxy aryl urea core, has absolute oral bioavailability of 30–70% in humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Betaxolol, a beta-1-selective blocker with a similar phenoxypropanolamine structure, has absolute bioavailability of 83.9 ± 6.6% after oral dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Pamatolol, a close phenoxypropanolamine analogue, shows essentially complete oral bioavailability ranging from 64.9% to 103.5%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Diacetolol, a related beta-blocker, has absolute bioavailability of 43 ± 7%, still clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Practolol, another immediate-release beta-blocker analogue, has reported oral bioavailability of 90–100%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is talinolol, a P-gp substrate beta-blocker. All highly transferable analogues with the same phenoxypropanolamine/aryl urea pharmacophore show absolute oral bioavailability well above 20% (30–100%). Rifampin co-treatment may reduce bioavailability through P-gp induction, but the low 20% threshold and high baseline F values make F < 20% unlikely.",
  "evidence_gaps": [
    "No direct rifampin co-treatment bioavailability data for the query or exact analogues; rifampin-mediated P-gp induction could lower F, but the expected magnitude is uncertain.",
    "No query-specific absolute bioavailability measurement under rifampin is available in the supplied evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

